205	/**
206	 * Persist a failed notification send so the failure is not silent.
207	 *
208	 * The notification channel (email) is the thing that broke, so we can't email
209	 * the user to tell them email failed. Instead we record it in
210	 * `email_send_failures`: the row is family-scoped (RLS) so the user sees an
211	 * in-app notice, and it doubles as the admin alert feed. Best-effort — a
212	 * logging failure must never break webhook processing.
213	 */
214	async function recordNotificationFailure(
215		supabase: SupabaseClient,
216		params: {
217			userId: string;
218			recipient: string;
219			notificationType: NotificationType;
220			originalSubject: string;
221			emailId?: string;
222			statusCode: number;
223			error: string;
224		}
225	): Promise<void> {
226		try {
227			const { error } = await supabase.from('email_send_failures').insert({
228				user_id: params.userId,
229				recipient: params.recipient,
230				notification_type: params.notificationType,
231				original_subject: params.originalSubject,
232				resend_email_id: params.emailId ?? null,
233				status_code: params.statusCode,
234				error: params.error
235			});
236			if (error) {
237				console.error('Failed to record notification failure:', JSON.stringify(error));
238			} else {
239				console.log(`Recorded notification failure for ${params.recipient} (admin alert queued)`);
240			}
241		} catch (err) {
242			console.error('Exception recording notification failure:', err);
243		}
244	}
245	
246	/**
247	 * Send a notification email and, if the send fails, record it durably so the
248	 * failure surfaces to the user (in-app) and to admins instead of vanishing into
249	 * the logs. Wraps the extracted `sendResendNotification` sender.
250	 */
251	async function sendNotificationEmail(
252		supabase: SupabaseClient,
253		userId: string,
254		apiKey: string,
255		toEmail: string,
256		notificationType: NotificationType,
257		title: string,
258		message: string,
259		originalSubject: string,
260		emailId?: string
261	): Promise<void> {
262		const result = await sendResendNotification(
263			apiKey,
264			toEmail,
265			notificationType,
266			title,
267			message,
268			originalSubject,
269			emailId
270		);
271	
272		if (!result.ok) {
273			await recordNotificationFailure(supabase, {
274				userId,
275				recipient: toEmail,
276				notificationType,
277				originalSubject,
278				emailId,
279				statusCode: result.status,
280				error: result.error ?? 'Unknown send failure'
281			});
282		}
283	}
284	
285	Deno.serve(async (req) => {
286		console.log('=== Resend Webhook Request Received ===');
287		console.log('Method:', req.method);
288		console.log('URL:', req.url);
289	
290		if (req.method !== 'POST') {
291			console.log('Rejecting non-POST request');
292			return jsonResponse(405, { error: 'Method not allowed' });
293		}
294	
295		// Read the raw body for signature verification
296		const bodyText = await req.text();
297		console.log('Received webhook payload length:', bodyText.length);
298		console.log('Raw payload:', bodyText.substring(0, 500) + (bodyText.length > 500 ? '...' : ''));
299	
300		let event: ResendWebhookEvent;
301	
302		try {
303			event = JSON.parse(bodyText);
304			console.log('Parsed event type:', event.type);
305			console.log('Event data:', JSON.stringify(event.data));
306		} catch (e) {
307			console.error('Failed to parse JSON:', e);
308			return jsonResponse(400, { error: 'Invalid JSON' });
309		}
310	
311		// Basic validation
312		if (!event.type) {
313			console.error('Missing event type in payload');
314			return jsonResponse(400, { error: 'Missing event type' });
315		}
316	
317		const supabaseUrl = Deno.env.get('SUPABASE_URL');
318		const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
319		const resendApiKey = Deno.env.get('RESEND_API_KEY');
320		const resendWebhookSecret = Deno.env.get('RESEND_WEBHOOK_SECRET');
321	
322		if (!supabaseUrl || !serviceRoleKey) {
323			return jsonResponse(500, { error: 'Missing Supabase env' });
324		}
325		if (!resendApiKey) {
326			console.error('RESEND_API_KEY environment variable is not set');
327			return jsonResponse(500, { error: 'Missing Resend API key' });
328		}
329	
330		console.log(`Resend API key is set (length: ${resendApiKey.length})`);
331	
332		// Log all request headers for debugging
333		console.log('Request headers:', JSON.stringify(Object.fromEntries(req.headers.entries())));
334	
335		// Verify the webhook signature — FAIL CLOSED. This endpoint runs with the
336		// service role and inserts receipts keyed on the sender's email, so an
337		// unauthenticated caller could forge an `email.received` event and inject
338		// receipts into any user's account (bypassing RLS). A missing secret is a
339		// server misconfiguration (500); a bad/absent signature is rejected (401).
340		// Never log the secret value.
341		if (!resendWebhookSecret) {
342			console.error('RESEND_WEBHOOK_SECRET is not set — refusing to process unverified webhook');
343			return jsonResponse(500, { error: 'Webhook signing secret not configured' });
344		}
345		if (!verifyWebhookSignature(req.headers, bodyText, resendWebhookSecret)) {
346			console.error('Invalid webhook signature — rejecting request');
347			return jsonResponse(401, { error: 'Invalid webhook signature' });
348		}
349		console.log('Webhook signature verification passed');
350	
351		// Only process email.received events
352		if (event.type !== 'email.received') {
353			console.log(`Ignoring event type: ${event.type} - returning success`);
354			return jsonResponse(200, { message: `Event type ${event.type} ignored` });
355		}
356	
357		console.log('Processing email.received event...');
358	
359		const supabase = createServiceClient(supabaseUrl, serviceRoleKey);
360	
361		// Find user by sender email. Resend delivers `from` as either a bare address
362		// or `Display Name <addr>` — extract the address so the exact-match lookup
363		// works regardless of the forwarding client's formatting.
364		const sender = parseSenderEmail(event.data?.from);
365		if (!sender) {
366			console.error('Missing or unparseable sender in event data:', event.data?.from);
367			return jsonResponse(400, { error: 'Missing sender' });
368		}
369	
370		console.log(`Looking up user by email: ${sender}`);
371		const { data: userIdData, error: userErr } = await supabase.rpc('find_user_by_email', {
372			email_address: sender
373		});
374		if (userErr) {
375			console.error(`Error finding user: ${JSON.stringify(userErr)}`);
376			return jsonResponse(500, { error: userErr.message });
377		}
378		if (!userIdData) {
379			console.error(`No user found for email: ${sender}`);
380			return jsonResponse(404, { error: 'User not found for sender email' });
381		}
382		const userId = userIdData as string;
383		console.log(`Found user ID: ${userId}`);
384	
385		// Fetch the full email content from Resend API to get body text
386		console.log(`Fetching email content for email_id: ${event.data.email_id}`);
387		console.log(
388			`Using API key: ${resendApiKey.substring(0, 7)}...${resendApiKey.substring(resendApiKey.length - 4)}`
389		);
390		console.log(`API endpoint: https://api.resend.com/emails/receiving/${event.data.email_id}`);
391	
392		let emailBodyText = '';
393	
394		try {
395			const emailResponse = await fetch(
396				`https://api.resend.com/emails/receiving/${event.data.email_id}`,
397				{
398					method: 'GET',
399					headers: {
400						Authorization: `Bearer ${resendApiKey}`,
401						'Content-Type': 'application/json'
402					}
403				}
404			);
405	
406			console.log(`Email fetch response status: ${emailResponse.status}`);
407	
408			if (!emailResponse.ok) {
409				const errorText = await emailResponse.text();
410				console.error(`Failed to fetch email: ${emailResponse.status} ${emailResponse.statusText}`);
411				console.error(`Error response body: ${errorText}`);
412				// Don't return error - continue with attachments processing
413			} else {
414				const email: ResendEmail = await emailResponse.json();
415				console.log(
416					`Email fetched successfully. Has text: ${!!email.text}, Has html: ${!!email.html}`
417				);
418				emailBodyText = (email.text || email.html || '').toString();
419			}
420		} catch (e) {
421			console.error('Exception fetching email content:', e);
422			// Continue processing - we can still try attachments
423		}
424	
425		// Single null-date handler shared by every insert path below: resolve the
426		// date (receipt date -> forwarded-email fallback -> none) and notify the user
427		// on a suspicious or missing date. Hoisted so all three paths behave alike.
428		const resolveDateAndNotify = async (
429			extracted: OcrResult,
430			filename?: string
431		): Promise<EmailReceiptDateResult> => {
432			const result = resolveEmailReceiptDate(
433				extracted.transaction_date ?? null,
434				extracted.raw_date_text ?? null,
435				emailBodyText,
436				new Date()
437			);
438			extracted.transaction_date = result.transaction_date;
439	
440			const src = filename ? ` from "${filename}"` : '';
441			if (result.suspicious_date) {
442				console.log(`Suspicious date for email receipt${src}: ${result.transaction_date}`);
443				await sendNotificationEmail(
444					supabase,
445					userId,
446					resendApiKey,
447					sender,
448					'warning',
449					'Please Check Receipt Date',
450					`The receipt date we found (${result.transaction_date})${src} seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
451					event.data.subject,
452					event.data.email_id
453				);
454			} else if (result.dateSource === 'none') {
455				console.log(`No date found for email receipt${src}; saving without a date`);
456				await sendNotificationEmail(
457					supabase,
458					userId,
459					resendApiKey,
460					sender,
461					'warning',
462					'Receipt Saved Without a Date',
463					`We couldn't find a date for your receipt${src}. We've saved it, but please open it in your expense tracker and add the correct date.`,
464					event.data.subject,
465					event.data.email_id
466				);
467			}
468			return result;
469		};
470	
471		// #{#eaf5a} Check for supported attachments before processing body text
472		const attachmentMetadata = event.data.attachments || [];
473		const hasScannable = hasSupportedAttachments(attachmentMetadata);
474	
475		let inserted: InsertedReceipt | null = null;
476		const processingErrors: string[] = [];
477	
478		// #{#eaf5a} Only process body text if no supported attachments exist
479		if (emailBodyText && !hasScannable) {
480			console.log('No supported attachments found, processing email body text');
481		} else if (hasScannable) {
482			console.log(
483				`Skipping body text extraction — ${attachmentMetadata.length} supported attachment(s) found`
484			);
485		}
486	
487		if (emailBodyText && !hasScannable) {
488			try {
489				console.log('Processing email body text with Mistral...');
490				const extracted = await processEmailText(emailBodyText);
491	
492				if (extracted) {
493					console.log('Mistral found receipt data:', JSON.stringify(extracted, null, 2));
494	
495					// Convert the text to an image
496					console.log('Converting text to image...');
497					const imageBytes = await textToImage(emailBodyText);
498					const { path, signedUrl } = await uploadToStorage(
499						supabase,
500						userId,
501						imageBytes,
502						'image/svg+xml',
503						'svg'
504					);
505					console.log('Image uploaded to:', signedUrl);
506	
507					// Insert receipt with the text-as-image
508					try {
509						console.log('Inserting receipt for user:', userId);
510	
511						// Resolve the date and notify on a suspicious/missing date (shared handler).
512						const dateResult = await resolveDateAndNotify(extracted);
513	
514						// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
515						const exchangeRate = await fetchRateForReceipt(
516							extracted.currency,
517							extracted.transaction_date
518						);
519	
520						inserted = await insertReceipt(supabase, {
521							user_id: userId,
522							receipt_image_path: path,
523							merchant_name: extracted.merchant_name,
524							total_amount: extracted.total_amount,
525							tax: extracted.tax,
526							transaction_date: extracted.transaction_date,
527							currency: extracted.currency,
528							exchange_rate_to_cad: exchangeRate,
529							credit_card_name: extracted.credit_card_name,
530							credit_card_last_4: extracted.credit_card_last_4,
531							suspicious_date: dateResult.suspicious_date
532						});
533						console.log('Receipt inserted successfully:', inserted?.id);
534					} catch (insertErr) {
535						const msg = `Body text insert failed: ${errText(insertErr)}`;
536						console.error(msg);
537						processingErrors.push(msg);
538					}
539				} else {
540					console.log('No receipt data found in email body text');
541					// Don't send notification yet - we'll try attachments first
542				}
543			} catch (e) {
544				const msg = `Body text processing error: ${errText(e)}`;
545				console.error(msg);
546				processingErrors.push(msg);
547			}
548		}
549	
550		// Process attachments (either as primary path or fallback from body text)
551		if (!inserted) {
552			console.log(`Found ${attachmentMetadata.length} attachment(s) in webhook payload`);
553	
554			if (attachmentMetadata.length === 0) {
555				console.log('No attachments to process');
556			} else {
557				// Fetch attachment download URLs from Resend API
558				console.log(`Fetching attachment download URLs for email_id: ${event.data.email_id}`);
559	
560				try {
561					const attachmentsResponse = await fetch(
562						`https://api.resend.com/emails/receiving/${event.data.email_id}/attachments`,
563						{
564							method: 'GET',
565							headers: {
566								Authorization: `Bearer ${resendApiKey}`,
567								'Content-Type': 'application/json'
568							}
569						}
570					);
571	
572					console.log(`Attachments fetch response status: ${attachmentsResponse.status}`);
573	
574					if (!attachmentsResponse.ok) {
575						const errorText = await attachmentsResponse.text();
576						const msg = `Resend attachment fetch failed: ${attachmentsResponse.status} ${attachmentsResponse.statusText} — ${errorText}`;
577						console.error(msg);
578						processingErrors.push(msg);
579					} else {
580						const attachmentsData = await attachmentsResponse.json();
581						console.log(`Attachments response data: ${JSON.stringify(attachmentsData)}`);
582						const attachments: ResendAttachment[] = attachmentsData.data || [];
583	
584						console.log(`Received ${attachments.length} attachment download URL(s)`);
585	
586						let processedCount = 0;
587	
588						for (const att of attachments) {
589							try {
590								// #{#eaf2a} Skip inline attachments (signatures, logos)
591								if (
592									isInlineAttachment({
593										filename: att.filename,
594										content_type: att.content_type,
595										content_id: att.content_id,
596										content_disposition: att.content_disposition
597									})
598								) {
599									console.log(
600										`Skipping inline attachment: ${att.filename} (content_id: ${att.content_id})`
601									);
602									continue;
603								}
604	
605								// #{#eaf1a} Filter by supported MIME types
606								const ct = att.content_type || 'application/octet-stream';
607								if (!isSupportedReceiptType(ct, att.filename)) {
608									console.log(`Skipping unsupported attachment type: ${ct} (${att.filename})`);
609									continue;
610								}
611	
612								console.log(`Processing attachment: ${att.filename}`);
613	
614								// Download attachment using the provided download_url
615								const downloadResponse = await fetch(att.download_url);
616								if (!downloadResponse.ok) {
617									const msg = `Download failed for ${att.filename}: HTTP ${downloadResponse.status}`;
618									console.error(msg);
619									processingErrors.push(msg);
620	
621									// Notify user about attachment download failure
622									await sendNotificationEmail(
623										supabase,
624										userId,
625										resendApiKey,
626										sender,
627										'error',
628										'Attachment Download Failed',
629										`We couldn't download the attachment "${att.filename}" from your email. Resend attachments expire after 30 minutes, so the download link may have expired. Please try forwarding the email again.`,
630										event.data.subject,
631										event.data.email_id
632									);
633	
634									continue;
635								}
636	
637								const bytes = new Uint8Array(await downloadResponse.arrayBuffer());
638								const ext = (att.filename?.split('.')?.pop() || 'bin').toLowerCase();
639	
640								const { path, signedUrl } = await uploadToStorage(supabase, userId, bytes, ct, ext);
641								const extracted = await ocrFromUrl(signedUrl, ct).catch(async (err) => {
642									const msg = `OCR failed for ${att.filename}: ${err?.message || err}`;
643									console.error(msg);
644									processingErrors.push(msg);
645	
646									// Notify user about OCR failure
647									await sendNotificationEmail(
648										supabase,
649										userId,
650										resendApiKey,
651										sender,
652										'error',
653										'Receipt Reading Failed',
654										`We couldn't extract receipt information from "${att.filename}". The image or PDF may be unclear, too dark, or rotated. Please try sending a clearer, well-lit photo of the receipt.`,
655										event.data.subject,
656										event.data.email_id
657									);
658	
659									return null;
660								});
661	
662								// #{#eaf3a} Validate OCR results before inserting
663								if (!extracted || !hasUsableOcrData(extracted)) {
664									const msg = `OCR returned no usable data for: ${att.filename} (merchant: ${extracted?.merchant_name ?? 'null'}, amount: ${extracted?.total_amount ?? 'null'})`;
665									console.log(msg);
666									processingErrors.push(msg);
667									continue;
668								}
669	
670								console.log('Inserting receipt from attachment for user:', userId);
671	
672								// Resolve the date and notify on a suspicious/missing date (shared handler).
673								const dateResult = await resolveDateAndNotify(extracted, att.filename);
674	
675								// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
676								const exchangeRate = await fetchRateForReceipt(
677									extracted.currency,
678									extracted.transaction_date
679								);
680	
681								inserted = await insertReceipt(supabase, {
682									user_id: userId,
683									receipt_image_path: path,
684									transaction_date: extracted.transaction_date,
685									total_amount: extracted.total_amount,
686									tax: extracted.tax,
687									merchant_name: extracted.merchant_name,
688									currency: extracted.currency,
689									exchange_rate_to_cad: exchangeRate,
690									credit_card_name: extracted.credit_card_name,
691									credit_card_last_4: extracted.credit_card_last_4,
692									suspicious_date: dateResult.suspicious_date
693								});
694								processedCount++;
695								console.log('Receipt from attachment inserted successfully');
696								// #{#eaf4a} No break — continue processing remaining attachments
697							} catch (e) {
698								const msg = `Attachment error (${att.filename}): ${errText(e)}`;
699								console.error(msg);
700								processingErrors.push(msg);
701							}
702						}
703	
704						console.log(
705							`Processed ${processedCount} receipt(s) from ${attachments.length} attachment(s)`
706						);
707					}
708				} catch (e) {
709					const msg = `Exception fetching attachment URLs: ${errText(e)}`;
710					console.error(msg);
711					processingErrors.push(msg);
712				}
713			}
714		}
715	
716		// #{#eaf5a} Fallback: if attachments were prioritized but none produced a receipt,
717		// try body text extraction as a last resort
718		if (!inserted && hasScannable && emailBodyText) {
719			console.log('No receipts from attachments, falling back to email body text');
720			try {
721				const extracted = await processEmailText(emailBodyText);
722	
723				if (extracted) {
724					console.log(
725						'Mistral found receipt data in body text (fallback):',
726						JSON.stringify(extracted, null, 2)
727					);
728	
729					const imageBytes = await textToImage(emailBodyText);
730					const { path } = await uploadToStorage(
731						supabase,
732						userId,
733						imageBytes,
734						'image/svg+xml',
735						'svg'
736					);
737	
738					// Resolve the date and notify on a suspicious/missing date (shared handler).
739					const dateResult = await resolveDateAndNotify(extracted);
740	
741					// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
742					const exchangeRate = await fetchRateForReceipt(
743						extracted.currency,
744						extracted.transaction_date
745					);
746	
747					inserted = await insertReceipt(supabase, {
748						user_id: userId,
749						receipt_image_path: path,
750						merchant_name: extracted.merchant_name,
751						total_amount: extracted.total_amount,
752						tax: extracted.tax,
753						transaction_date: extracted.transaction_date,
754						currency: extracted.currency,
755						exchange_rate_to_cad: exchangeRate,
756						credit_card_name: extracted.credit_card_name,
757						credit_card_last_4: extracted.credit_card_last_4,
758						suspicious_date: dateResult.suspicious_date
759					});
760					console.log('Receipt inserted from body text (fallback):', inserted?.id);
761				}
762			} catch (e) {
763				const msg = `Body text fallback error: ${errText(e)}`;
764				console.error(msg);
765				processingErrors.push(msg);
766			}
767		}
768	
769		if (!inserted) {
770			// No receipt was found in email body or attachments - notify user
771			await sendNotificationEmail(
772				supabase,
773				userId,
774				resendApiKey,
775				sender,
776				'error',
777				'No Receipt Found',
778				`We couldn't find any receipt information in your email or attachments. Please make sure you're forwarding a clear receipt photo or PDF. If you're forwarding text-only emails, they may not contain receipt data we can extract.`,
779				event.data.subject,
780				event.data.email_id
781			);
782	
783			console.error('Processing failed. Errors:', JSON.stringify(processingErrors));
784			return jsonResponse(422, {
785				error: 'No valid receipt found in email body or attachments',
786				details: processingErrors,
787				email_id: event.data.email_id,
788				attachments_count: attachmentMetadata.length,
789				had_body_text: !!emailBodyText,
790				had_scannable_attachments: hasScannable
791			});
792		}
793	
794		// Success! Send confirmation email
795		const merchantInfo = inserted.merchant_name ? ` from ${inserted.merchant_name}` : '';
796		const amountInfo = inserted.total_amount ? ` for $${inserted.total_amount}` : '';
797	
798		await sendNotificationEmail(
799			supabase,
800			userId,
801			resendApiKey,
802			sender,
803			'success',
804			'Receipt Added Successfully',
805			`Your receipt${merchantInfo}${amountInfo} has been added to your expense tracker. You can view and edit it at any time in your receipts page.`,
806			event.data.subject,
807			event.data.email_id
808		);
809	
